head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods16010";
scwin.discls_minute = 4;
scwin.discls_second = 59;
scwin.discls_timer = undefined;
scwin.result = null;
scwin.checkIdAjax = null;
scwin.ipt_sendPhoneAuth = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — sType, sMessage
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.checkResult();
        $("#ipt_bPw").bind("focus", function() {
                $("#text_oldid").text("");
        });
        $("#ipt_bPw").bind("focusout", function() {
                if ($(this).val().length === 0) {
                    $("#text_oldid").text("현재 비밀번호");
                }
        });
        $("#pw").bind("focus", function() {
                $("#text_newpw").text("");
        });
        $("#pw").bind("focusout", function() {
                if ($(this).val().length === 0) {
                    $("#text_newpw").text("새 비밀번호");
                }
        });
        $("#ipt_pwChk").bind("focus", function() {
                $("#text_newpw2").text("");
        });
        $("#ipt_pwChk").bind("focusout", function() {
                if ($(this).val().length === 0) {
                    $("#text_newpw2").text("새 비밀번호 확인");
                }
        });

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods16010.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.checkIdAjax = scwin.tx_checkIdAjax;
        scwin.ipt_sendPhoneAuth = scwin.tx_sendPhoneAuth;
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods16010.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
